// Paw Sweep service worker. GENERATED by `npm run build` from scripts/sw.template.js.
// Do not edit sw.js by hand: edit the template and rebuild.
const CACHE = "__CACHE__";
const ASSETS = __ASSETS__;

// Download every file up front so the whole game works offline after the first visit.
// cache: "reload" skips the browser's own HTTP cache, so a new version never re-saves stale copies of files
// (this is what made iPad Safari keep old files even after the service worker updated).
self.addEventListener("install", event => {
  event.waitUntil(
    caches.open(CACHE)
      .then(cache => Promise.all(ASSETS.map(url => cache.add(new Request(url, { cache: "reload" })))))
      .then(() => self.skipWaiting())
  );
});

// Delete caches from older releases
self.addEventListener("activate", event => {
  event.waitUntil(
    caches.keys()
      .then(keys => Promise.all(keys.filter(k => k.startsWith("paw-sweep-") && k !== CACHE).map(k => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

// Cache first, network as a fallback. Pages fall back to the cached app shell.
// Audio/video send Range requests (Safari insists on them), so answer those with a slice of the cached file.
async function rangeResponse(req, hit) {
  const m = /bytes=(\d*)-(\d*)/.exec(req.headers.get("range"));
  const buf = await hit.arrayBuffer();
  const start = m[1] ? parseInt(m[1], 10) : 0;
  const end = m[2] ? Math.min(parseInt(m[2], 10), buf.byteLength - 1) : buf.byteLength - 1;
  return new Response(buf.slice(start, end + 1), {
    status: 206,
    statusText: "Partial Content",
    headers: {
      "Content-Type": hit.headers.get("Content-Type") || "audio/mpeg",
      "Content-Range": `bytes ${start}-${end}/${buf.byteLength}`,
      "Content-Length": String(end - start + 1),
    },
  });
}

self.addEventListener("fetch", event => {
  const req = event.request;
  if (req.method !== "GET" || new URL(req.url).origin !== self.location.origin) return;

  event.respondWith(
    caches.match(req, { ignoreSearch: true }).then(hit => {
      if (hit) return req.headers.has("range") ? rangeResponse(req, hit) : hit;
      return fetch(req).catch(() => (req.mode === "navigate" ? caches.match("./") : Response.error()));
    })
  );
});
